#!/usr/bin/env bash
# build.sh — build and run the mel front-end gates (voice loop, native/mel).
#
#   ./build.sh fft      # 400-point FFT vs numpy's rfft (two vectors)
#   ./build.sh mel      # full log-mel vs WhisperFeatureExtractor (filters + 80x3000)
#   ./build.sh gold     # regenerate the reference artifacts (~/miniconda/bin/python)
#   ./build.sh all      # fft + mel
#
# The gold artifacts under native/mel/gold/ are generated by oracle_mel.py; the
# checkers are the gates. Vyb prints results as integers scaled by a power of ten
# (its float->String keeps only 6 significant digits), so the comparison runs in
# Python against the float32 references.
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
cd "$here"

VYBHOME="${VYBHOME:-$HOME/Projects/Vyb}"
VYB="${VYB:-$VYBHOME/build/vyb}"
export VYB_STDLIB="${VYB_STDLIB:-$VYBHOME/stdlib}"
PY="${PY:-$HOME/miniconda/bin/python}"

build() {   # build() <probe>
    echo "== vyb --build $1"
    "$VYB" "$1.vyb" --module-path . --build "$1"
}

run_gold() {
    echo "== oracle (regenerates gold/)"
    "$PY" oracle_mel.py
}

run_fft() {
    build fft_probe
    echo "== fft gate"
    ./fft_probe > vyb_fft.txt
    "$PY" check_fft.py vyb_fft.txt
}

run_mel() {
    build mel_probe
    echo "== mel gate"
    ./mel_probe > vyb_mel.txt
    "$PY" check_mel.py vyb_mel.txt
}

case "${1:-all}" in
    fft)  run_fft ;;
    mel)  run_mel ;;
    gold) run_gold ;;
    all)  run_fft; run_mel ;;
    *)    echo "usage: $0 [fft|mel|gold|all]" >&2; exit 2 ;;
esac
